import json,glob
def walk(node,path,out,step,case,ep):
    if isinstance(node,list):
        if len(node)>=2 and all(isinstance(x,(dict,list)) for x in node):
            out.append((case,step,path,len(node),ep))
        for i,x in enumerate(node): walk(x,path+'[%d]'%i,out,step,case,ep)
    elif isinstance(node,dict):
        for k,v in node.items(): walk(v,path+'.'+k,out,step,case,ep)
out=[]
for f in glob.glob('judge/cases/*/*.json'):
    d=json.load(open(f,encoding='utf-8'))
    for name,pred in (d.get('predicted') or {}).items():
        walk(pred.get('body') or {},'body',out,name,d.get('id'),d.get('endpoint'))
print(len(out))
seen=set()
for t in out:
    k=(t[0],t[1],t[2].split('[')[0])
    if k in seen: continue
    seen.add(k); print(t)
"
